from taf.sbts.oam.coam.admin import admin

from taf.rfrl.procedures.resources.python.logger import log_input_and_output


@log_input_and_output
def start_antenna_online_monitoring(target_dns, connection, timeout=30):
    """
    Start ANTL online monitoring via admin CLI.
    :param target_dns: list of ANTL_R infomodel runtime distnames
    :type target_dns: list
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param timeout: timeout to wait for positive procedure result, default is 30 second
    :type timeout: int
    :return: one of statuses: ['Waiting for response', 'Rejected', 'Failed', 'Succeeded']
    :rtype: str
    """
    adm = admin()
    return adm.start_antl_online_monitoring(target_dns=target_dns,
                                            connection=connection,
                                            timeout=timeout)


@log_input_and_output
def stop_antenna_online_monitoring(output_file_path, connection, timeout=30):
    """
    Stop ANTL online monitoring via admin CLI. Save ant online monitoring data to output_file_path.
    :param output_file_path: path to save ANTL monitoring json data, please use absolute path, e.g.:/tmp/antenna_result
    :type output_file_path: str
    :param connection: adminConnection object or, if used, string name alias.
    :type connection: adminConnection or str
    :param timeout: timeout to wait for positive procedure result, default is 30 second
    :type timeout: int
    :return: one of statuses: ['Waiting for response', 'Rejected', 'Failed', 'Succeeded']
    :rtype: str
    """
    adm = admin()
    return adm.stop_antl_online_monitoring(output_file_name=output_file_path,
                                           connection=connection,
                                           timeout=timeout)
